import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { UtteranceType, type Utterance } from "../../../types";
import { UserMessage } from "./UserMessage";

const baseUtterance: Omit<Utterance, "entities"> = {
  __typename: "Utterance",
  id: "u1",
  type: UtteranceType.User,
  text: "/SetSlots(account_type=premium)",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  tokens: [],
  rephrase: false,
  rephrasePrompt: null,
  metadata: { parseData: {} },
};

describe("UserMessage", () => {
  describe("text rendering", () => {
    it("renders the utterance text when no button metadata is present", () => {
      renderWithProviders(<UserMessage utterance={baseUtterance} inspectorMode={false} />);
      expect(screen.getByText("/SetSlots(account_type=premium)")).toBeInTheDocument();
    });

    it("renders the button title when user_message_type is button_click", () => {
      const utterance = {
        ...baseUtterance,
        metadata: {
          parseData: {},
          user_message_type: "button_click" as const,
          button_title: "Yes",
        },
      };
      renderWithProviders(<UserMessage utterance={utterance} inspectorMode={false} />);
      expect(screen.getByText("Yes")).toBeInTheDocument();
      expect(screen.queryByText("/SetSlots(account_type=premium)")).not.toBeInTheDocument();
    });

    it("renders the utterance text when user_message_type is present but button_title is missing", () => {
      const utterance = {
        ...baseUtterance,
        metadata: {
          parseData: {},
          user_message_type: "button_click" as const,
        },
      };
      renderWithProviders(<UserMessage utterance={utterance} inspectorMode={false} />);
      expect(screen.getByText("/SetSlots(account_type=premium)")).toBeInTheDocument();
    });

    it("renders the utterance text when user_message_type is not button_click", () => {
      const utterance = {
        ...baseUtterance,
        metadata: {
          parseData: {},
          button_title: "Yes",
        },
      };
      renderWithProviders(<UserMessage utterance={utterance} inspectorMode={false} />);
      expect(screen.getByText("/SetSlots(account_type=premium)")).toBeInTheDocument();
      expect(screen.queryByText("Yes")).not.toBeInTheDocument();
    });
  });
});
